    Raises ValueError if n is negative or is not a perfect square.
    """
    if n < 0:
        raise ValueError("negative input")
    # Bit-level integer Newton's method; exact for arbitrarily large n.
    if n == 0:
        return 0
    x = 1 << ((n.bit_length() + 1) // 2)
    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y
    if x * x != n:
        raise ValueError("%d is not a perfect square" % n)
    return x

